# -- format_event_time --------------------------------------------------------


def test_format_event_time_datetime():
    assert format_event_time("2026-03-30T14:30:00-04:00") == "14:30"


def test_format_event_time_date_only():
    assert format_event_time("2026-03-30") == ""


def test_format_event_time_empty():
    assert format_event_time("") == ""


def test_format_event_time_short_string():
    assert format_event_time("2026-03") == ""


def test_format_event_time_invalid():
    result = format_event_time("not-a-date-time")
    assert result == "not-a"


# -- atomic_write_json --------------------------------------------------------


def test_atomic_write_json_creates_file(tmp_path):
    path = tmp_path / "test.json"
    atomic_write_json(path, {"key": "value"})
    assert path.exists()
    assert json.loads(path.read_text()) == {"key": "value"}


def test_atomic_write_json_with_kwargs(tmp_path):
    path = tmp_path / "test.json"
    atomic_write_json(path, {"b": 2, "a": 1}, indent=2, sort_keys=True)
    content = path.read_text()
    assert '"a": 1' in content
    assert '"b": 2' in content


def test_atomic_write_json_creates_parent_dirs(tmp_path):
    path = tmp_path / "nested" / "dir" / "test.json"
    atomic_write_json(path, [1, 2, 3])
    assert path.exists()
    assert json.loads(path.read_text()) == [1, 2, 3]


def test_atomic_write_json_overwrites_existing(tmp_path):
    path = tmp_path / "test.json"
    atomic_write_json(path, {"old": True})
    atomic_write_json(path, {"new": True})
    assert json.loads(path.read_text()) == {"new": True}


# -- atomic_write_text --------------------------------------------------------


def test_atomic_write_text_creates_file(tmp_path):
    path = tmp_path / "test.txt"
    atomic_write_text(path, "hello world")
    assert path.read_text() == "hello world"


def test_atomic_write_text_creates_parent_dirs(tmp_path):
    path = tmp_path / "nested" / "test.txt"
    atomic_write_text(path, "content")
    assert path.read_text() == "content"


def test_atomic_write_text_overwrites_existing(tmp_path):
    path = tmp_path / "test.txt"
    atomic_write_text(path, "old")
    atomic_write_text(path, "new")
    assert path.read_text() == "new"
